from qiskit import QuantumCircuit
from typing import List
import math


def calculate_total_value_of_selected_items(qc: QuantumCircuit, values: List[int], selection: List[int], result: List[int]) -> QuantumCircuit:
    n = len(result)
    if n == 0:
        return qc
    # QFT (little endian, no swaps)
    for j in range(n - 1, -1, -1):
        qc.h(result[j])
        for k in range(j - 1, -1, -1):
            qc.cp(math.pi / (2 ** (j - k)), result[k], result[j])
    # controlled additions in Fourier space
    for v, s in zip(values, selection):
        for j in range(n):
            ang = 2 * math.pi * (v % (2 ** n)) / (2 ** (j + 1))
            if (v % (2 ** n)) != 0:
                qc.cp(ang, s, result[j])
    # inverse QFT
    for j in range(n):
        for k in range(j):
            qc.cp(-math.pi / (2 ** (j - k)), result[k], result[j])
        qc.h(result[j])
    return qc

