from qiskit import QuantumCircuit
from typing import List


def compare_qubit_array_leq_than_int(qc: QuantumCircuit, register: List[int], threshold: int, target: int) -> QuantumCircuit:
    n = len(register)
    c = threshold + 1
    if c <= 0:
        return qc
    if c >= (1 << n):
        qc.x(target)
        return qc
    for i in range(n):
        if (c >> i) & 1:
            controls = list(register[i:])
            flips = []
            for k, q in enumerate(controls):
                bit = 0 if k == 0 else (c >> (i + k)) & 1
                if bit == 0:
                    flips.append(q)
            for q in flips:
                qc.x(q)
            if len(controls) == 1:
                qc.cx(controls[0], target)
            else:
                qc.mcx(controls, target)
            for q in flips:
                qc.x(q)
    return qc

