import math
from qiskit import QuantumCircuit
from qiskit.circuit.library import QFT
from typing import List


def _add_weights(qc, weights, selection, weight_reg, sign):
    n = len(weight_reg)
    if n == 0:
        return
    qft = QFT(n, do_swaps=False).to_gate()
    iqft = QFT(n, do_swaps=False, inverse=True).to_gate()
    qc.append(qft, list(weight_reg))
    for i, w in enumerate(weights):
        if i >= len(selection):
            break
        for j in range(n):
            ang = sign * 2 * math.pi * w / (2 ** (n - j))
            if (w % (2 ** (n - j))) != 0:
                qc.cp(ang, selection[i], weight_reg[j])
    qc.append(iqft, list(weight_reg))


def verify_total_weight_constraint(qc: QuantumCircuit, weights: List[int], selection: List[int], weight_reg: List[int], capacity: int, target: int) -> QuantumCircuit:
    n = len(weight_reg)
    _add_weights(qc, weights, selection, weight_reg, 1)
    if capacity >= 0:
        top = min(capacity, 2 ** n - 1)
        if top == 2 ** n - 1:
            qc.x(target)
        else:
            for v in range(top + 1):
                qc.mcx(list(weight_reg), target, ctrl_state=v)
    _add_weights(qc, weights, selection, weight_reg, -1)
    return qc

