from qiskit import QuantumCircuit
from qiskit.circuit.library import MCXGate
from typing import List


def verify_01_knapsack_solution(qc: QuantumCircuit, values: List[int], weights: List[int], selection: List[int], capacity: int, min_profit: int, target: int) -> QuantumCircuit:
    n = len(selection)
    valid = []
    for mask in range(1 << n):
        w = 0
        v = 0
        for i in range(n):
            if (mask >> i) & 1:
                w += weights[i]
                v += values[i]
        valid.append(w <= capacity and v >= min_profit)
    if n == 0:
        if valid[0]:
            qc.x(target)
        return qc
    num_valid = sum(valid)
    if num_valid * 2 > (1 << n):
        qc.x(target)
        flip_set = [m for m in range(1 << n) if not valid[m]]
    else:
        flip_set = [m for m in range(1 << n) if valid[m]]
    for mask in flip_set:
        qc.append(MCXGate(n, ctrl_state=mask), list(selection) + [target])
    return qc

