from qiskit import QuantumCircuit
from typing import List
import itertools

def _cubes(qubits, L):
    n = len(qubits)
    if L < 0:
        return []
    if L >= (1 << n) - 1:
        return [{}]
    cubes = []
    for k in range(n - 1, -1, -1):
        if (L >> k) & 1:
            c = {}
            for j in range(n - 1, k, -1):
                c[qubits[j]] = (L >> j) & 1
            c[qubits[k]] = 0
            cubes.append(c)
    c = {}
    for j in range(n):
        c[qubits[j]] = (L >> j) & 1
    cubes.append(c)
    return cubes

def verify_limits_satisfaction(qc: QuantumCircuit, jagged: List[List[int]], limits: List[int], target: int) -> QuantumCircuit:
    per_item = []
    for qubits, L in zip(jagged, limits):
        cs = _cubes(list(qubits), L)
        if not cs:
            return qc
        per_item.append(cs)
    for combo in itertools.product(*per_item):
        fixed = {}
        for c in combo:
            fixed.update(c)
        controls = list(fixed.keys())
        if not controls:
            qc.x(target)
            continue
        state = 0
        for idx, q in enumerate(controls):
            if fixed[q]:
                state |= (1 << idx)
        if len(controls) == 1:
            if fixed[controls[0]]:
                qc.cx(controls[0], target)
            else:
                qc.x(controls[0])
                qc.cx(controls[0], target)
                qc.x(controls[0])
        else:
            qc.mcx(controls, target, ctrl_state=state)
    return qc

