import math
from qiskit import QuantumCircuit
from typing import List


def _qft(qc, reg):
    n = len(reg)
    for j in range(n - 1, -1, -1):
        qc.h(reg[j])
        for k in range(j):
            qc.cp(2 * math.pi / (2 ** (j - k + 1)), reg[k], reg[j])


def _iqft(qc, reg):
    n = len(reg)
    for j in range(n):
        for k in range(j - 1, -1, -1):
            qc.cp(-2 * math.pi / (2 ** (j - k + 1)), reg[k], reg[j])
        qc.h(reg[j])


def increment_by_product(qc: QuantumCircuit, quantity: List[int], coefficient: int, result: List[int]) -> QuantumCircuit:
    n = len(result)
    if n == 0:
        return qc
    _qft(qc, result)
    for i, q in enumerate(quantity):
        for j in range(n):
            num = (coefficient * (2 ** i)) % (2 ** (j + 1))
            if num == 0:
                continue
            angle = 2 * math.pi * num / (2 ** (j + 1))
            qc.cp(angle, q, result[j])
    _iqft(qc, result)
    return qc

