from qiskit import QuantumCircuit
from typing import List


def calculate_total_value_bounded(qc: QuantumCircuit, values: List[int], jagged: List[List[int]], result: List[int]) -> QuantumCircuit:
    n = len(result)
    if n == 0:
        return qc
    # QFT (little-endian, no swaps)
    for k in range(n):
        qc.h(result[k])
    for k in range(n):
        for m in range(k):
            qc.cp(2 * math.pi / (2 ** (k - m + 1)), result[m], result[k])
    # controlled constant additions in Fourier space
    for i, reg in enumerate(jagged):
        v = values[i]
        for j, ctrl in enumerate(reg):
            c = v << j
            for k in range(n):
                cm = c % (2 ** (k + 1))
                if cm == 0:
                    continue
                ang = 2 * math.pi * cm / (2 ** (k + 1))
                qc.cp(ang, ctrl, result[k])
    # inverse QFT
    for k in range(n - 1, -1, -1):
        for m in range(k - 1, -1, -1):
            qc.cp(-2 * math.pi / (2 ** (k - m + 1)), result[m], result[k])
    for k in range(n):
        qc.h(result[k])
    return qc

