from qiskit import QuantumCircuit
from typing import List
import itertools


def verify_bounded_weight_constraint(qc: QuantumCircuit, weights: List[int], jagged: List[List[int]], capacity: int, target: int) -> QuantumCircuit:
    n_items = min(len(weights), len(jagged))
    ranges = [range(2 ** len(jagged[i])) for i in range(n_items)]
    good = []
    bad = []
    for combo in itertools.product(*ranges):
        total = sum(weights[i] * combo[i] for i in range(n_items))
        if total <= capacity:
            good.append(combo)
        else:
            bad.append(combo)

    def apply(combos):
        for combo in combos:
            controls = []
            flips = []
            for i in range(n_items):
                reg = jagged[i]
                v = combo[i]
                for b, q in enumerate(reg):
                    controls.append(q)
                    if not ((v >> b) & 1):
                        flips.append(q)
            for q in flips:
                qc.x(q)
            if len(controls) == 0:
                qc.x(target)
            elif len(controls) == 1:
                qc.cx(controls[0], target)
            else:
                qc.mcx(controls, target)
            for q in flips:
                qc.x(q)

    if len(good) <= len(bad):
        apply(good)
    else:
        qc.x(target)
        apply(bad)
    return qc

