import random
from typing import Tuple
from qiskit import QuantumCircuit
from qiskit_aer import AerSimulator


def bb84_protocol_with_eavesdropper(n_qubits: int, eve_probability: float = 1.0) -> Tuple[bool, list, list, float]:
    alice_bits = [random.randint(0, 1) for _ in range(n_qubits)]
    alice_bases = [random.randint(0, 1) for _ in range(n_qubits)]
    bob_bases = [random.randint(0, 1) for _ in range(n_qubits)]
    bob_results = []
    for i in range(n_qubits):
        # state sent by Alice: (bit, basis)
        bit = alice_bits[i]
        basis = alice_bases[i]
        if random.random() < eve_probability:
            eve_basis = random.randint(0, 1)
            if eve_basis == basis:
                eve_bit = bit
            else:
                eve_bit = random.randint(0, 1)
            # Eve resends the state she measured
            bit = eve_bit
            basis = eve_basis
        if bob_bases[i] == basis:
            bob_bit = bit
        else:
            bob_bit = random.randint(0, 1)
        bob_results.append(bob_bit)
    alice_key = []
    bob_key = []
    for i in range(n_qubits):
        if alice_bases[i] == bob_bases[i]:
            alice_key.append(alice_bits[i])
            bob_key.append(bob_results[i])
    if len(alice_key) > 0:
        errors = sum(1 for a, b in zip(alice_key, bob_key) if a != b)
        error_rate = errors / len(alice_key)
    else:
        error_rate = 0.0
    success = bool(error_rate < 0.11)
    return success, alice_key, bob_key, float(error_rate)

