from typing import List


def multi_target_oracle(qc: QuantumCircuit, query: List[int], target: int, pattern: List[bool]) -> QuantumCircuit:
    """
    Oracle that marks a specific bit pattern.
    Flips target iff the query register matches pattern (query[i] == pattern[i]).
    """
    n = len(query)
    zeros = [query[i] for i in range(n) if not pattern[i]]
    for q in zeros:
        qc.x(q)
    if n == 0:
        qc.x(target)
    elif n == 1:
        qc.cx(query[0], target)
    else:
        qc.mcx(list(query), target)
    for q in zeros:
        qc.x(q)
    return qc

