def arithmetic_oracle(qc: QuantumCircuit, query: List[int], target: int, threshold: int) -> QuantumCircuit:
    n = len(query)
    if threshold <= 0:
        return qc
    if threshold >= (1 << n):
        qc.x(target)
        return qc
    for i in range(n):
        if (threshold >> i) & 1:
            controls = list(query[i:])
            state = 0
            for j in range(len(controls)):
                if j == 0:
                    bit = 0
                else:
                    bit = (threshold >> (i + j)) & 1
                state |= (bit << j)
            qc.mcx(controls, target, ctrl_state=state)
    return qc

