from qiskit import QuantumCircuit
from typing import List
from itertools import combinations


def bit_counting_oracle(qc: QuantumCircuit, query: List[int], target: int, k: int) -> QuantumCircuit:
    query = list(query)
    n = len(query)
    if k < 0 or k > n:
        return qc
    if n == 0:
        if k == 0:
            qc.x(target)
        return qc
    for ones in combinations(range(n), k):
        ones_set = set(ones)
        zeros = [query[i] for i in range(n) if i not in ones_set]
        for q in zeros:
            qc.x(q)
        if n == 1:
            qc.cx(query[0], target)
        else:
            qc.mcx(query, target)
        for q in zeros:
            qc.x(q)
    return qc

