def divisibility_oracle(qc: QuantumCircuit, query: List[int], target: int, divisor: int) -> QuantumCircuit:
    n = len(query)
    if divisor == 0:
        return qc
    for x in range(2 ** n):
        if x % divisor != 0:
            continue
        zeros = [query[i] for i in range(n) if not (x >> i) & 1]
        for q in zeros:
            qc.x(q)
        if n == 0:
            qc.x(target)
        elif n == 1:
            qc.cx(query[0], target)
        else:
            qc.mcx(list(query), target)
        for q in zeros:
            qc.x(q)
