from qiskit import QuantumCircuit
from typing import List


def equality_oracle(qc: QuantumCircuit, reg_a: List[int], reg_b: List[int], target: int) -> QuantumCircuit:
    """Oracle that marks states where reg_a == reg_b."""
    n = min(len(reg_a), len(reg_b))
    # XOR b into a: a_i becomes 0 iff a_i == b_i
    for i in range(n):
        qc.cx(reg_b[i], reg_a[i])
    # flip all a bits so equal -> 1
    for i in range(n):
        qc.x(reg_a[i])
    if n == 0:
        qc.x(target)
    elif n == 1:
        qc.cx(reg_a[0], target)
    else:
        qc.mcx(list(reg_a[:n]), target)
    # uncompute
    for i in range(n):
        qc.x(reg_a[i])
    for i in range(n):
        qc.cx(reg_b[i], reg_a[i])
    return qc

