def exactly_one_bit_true() -> TruthTable:
    """Return a truth table for the function that is true iff exactly 1 bit is true.

    For three input bits (x3, x2, x1) the function is true for the inputs
    (0,0,1), (0,1,0) and (1,0,0). Using the standard ordering where the index
    is x1 + 2*x2 + 4*x3, the corresponding bits are at positions 1, 2 and 4.
    Hence the integer representation is 2 + 4 + 16 = 22.
    """
    return TruthTable(22, 3)

