from qiskit import QuantumCircuit

def oracle_hamming_with_prefix(qc: QuantumCircuit, x: list[int], y: int, prefix: list[int]) -> QuantumCircuit:
    P = len(prefix)
    assert 1 <= P <= len(x), "P should be between 1 and N, inclusive"
    # parity part
    for q in x:
        qc.cx(q, y)
    # prefix match part
    for i in range(P):
        if not prefix[i]:
            qc.x(x[i])
    if P == 1:
        qc.cx(x[0], y)
    else:
        qc.mcx(list(x[:P]), y)
    for i in range(P):
        if not prefix[i]:
            qc.x(x[i])
    return qc

