from qiskit import QuantumCircuit


def grover_diffusion(qc: QuantumCircuit, qubits: list) -> QuantumCircuit:
    """
    Apply Grover diffusion operator (inversion about the mean):
    H^n X^n (multi-controlled Z) X^n H^n
    """
    qubits = list(qubits)
    n = len(qubits)
    if n == 0:
        return qc
    for q in qubits:
        qc.h(q)
    for q in qubits:
        qc.x(q)
    if n == 1:
        qc.z(qubits[0])
    elif n == 2:
        qc.cz(qubits[0], qubits[1])
    else:
        target = qubits[-1]
        controls = qubits[:-1]
        qc.h(target)
        qc.mcx(controls, target)
        qc.h(target)
    for q in qubits:
        qc.x(q)
    for q in qubits:
        qc.h(q)
    return qc

