from qiskit import QuantumCircuit, QuantumRegister


def _mcz(qc, qubits):
    qubits = list(qubits)
    if len(qubits) == 0:
        return
    if len(qubits) == 1:
        qc.z(qubits[0])
        return
    if len(qubits) == 2:
        qc.cz(qubits[0], qubits[1])
        return
    t = qubits[-1]
    qc.h(t)
    qc.mcx(qubits[:-1], t)
    qc.h(t)


def _edge_compute(qc, ca, cb, e):
    for x, y in zip(ca, cb):
        qc.cx(x, y)
        qc.x(y)
    qc.mcx(list(cb), e)
    for x, y in reversed(list(zip(ca, cb))):
        qc.x(y)
        qc.cx(x, y)


def grover_iteration(qc: QuantumCircuit, colors: list, edges: list) -> QuantumCircuit:
    edges = list(edges)
    if len(edges) > 0:
        anc = QuantumRegister(len(edges), 'edge_anc')
        qc.add_register(anc)
        for i, (v1, v2) in enumerate(edges):
            _edge_compute(qc, colors[v1], colors[v2], anc[i])
        # phase flip when no edge is monochromatic (all ancillas 0)
        for i in range(len(edges)):
            qc.x(anc[i])
        _mcz(qc, [anc[i] for i in range(len(edges))])
        for i in range(len(edges)):
            qc.x(anc[i])
        for i in reversed(range(len(edges))):
            v1, v2 = edges[i]
            _edge_compute(qc, colors[v1], colors[v2], anc[i])
    # diffusion over color qubits
    flat = []
    for reg in colors:
        for q in reg:
            flat.append(q)
    for q in flat:
        qc.h(q)
    for q in flat:
        qc.x(q)
    _mcz(qc, flat)
    for q in flat:
        qc.x(q)
    for q in flat:
        qc.h(q)
    return qc

