    def is_valid_coloring(coloring):
        for u, v in edges:
            if coloring[u] == coloring[v]:
                return False
        return True

    def generate_colorings(current_coloring=[]):
        if len(current_coloring) == num_vertices:
            return 1 if is_valid_coloring(current_coloring) else 0
        count = 0
        for color in range(num_colors):
            current_coloring.append(color)
            count += generate_colorings(current_coloring)
            current_coloring.pop()
        return count

