def count_valid_colorings(num_vertices: int, edges: list, num_colors: int = 4) -> int:
    n = int(num_vertices)
    k = int(num_colors)
    if n <= 0:
        return 1
    adj = [set() for _ in range(n)]
    for e in edges:
        a, b = e[0], e[1]
        if a == b:
            return 0
        adj[a].add(b)
        adj[b].add(a)
    # Count by connected components using backtracking with memo-free DFS ordering
    order = []
    seen = [False] * n
    for s in range(n):
        if seen[s]:
            continue
        seen[s] = True
        stack = [s]
        while stack:
            u = stack.pop()
            order.append(u)
            for w in adj[u]:
                if not seen[w]:
                    seen[w] = True
                    stack.append(w)
    # Backtracking with symmetry: count per component separately
    color = [-1] * n
    pos = {v: i for i, v in enumerate(order)}
    # split into components
    comp = [-1] * n
    comps = []
    for s in range(n):
        if comp[s] != -1:
            continue
        cid = len(comps)
        comp[s] = cid
        lst = [s]
        stack = [s]
        while stack:
            u = stack.pop()
            for w in adj[u]:
                if comp[w] == -1:
                    comp[w] = cid
                    lst.append(w)
                    stack.append(w)
        comps.append(lst)
    total = 1
    for lst in comps:
        # BFS order within component so each vertex (after first) has a colored neighbor
        start = lst[0]
        ordv = [start]
        vis = {start}
        i = 0
        while i < len(ordv):
            u = ordv[i]
            i += 1
            for w in sorted(adj[u]):
                if w not in vis:
                    vis.add(w)
                    ordv.append(w)
        m = len(ordv)

        def rec(idx):
            if idx == m:
                return 1
            v = ordv[idx]
            used = set()
            for w in adj[v]:
                if color[w] != -1:
                    used.add(color[w])
            cnt = 0
            for c in range(k):
                if c not in used:
                    color[v] = c
                    cnt += rec(idx + 1)
            color[v] = -1
            return cnt

        total *= rec(0)
        if total == 0:
            return 0
    return total

