import numpy as np
from typing import List, Tuple


def _backtrack(n, edges, k):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        if u != v:
            adj[u].append(v)
            adj[v].append(u)
    col = [-1] * n

    def rec(i):
        if i == n:
            return True
        for c in range(k):
            if all(col[j] != c for j in adj[i] if j < i):
                col[i] = c
                if rec(i + 1):
                    return True
        col[i] = -1
        return False

    if rec(0):
        return list(col)
    return None


def _valid(col, edges, k):
    if any(c < 0 or c >= k for c in col):
        return False
    return all(col[u] != col[v] for u, v in edges if u != v)


def solve_graph_coloring(num_vertices: int, edges: List[Tuple[int, int]], num_iterations: int = 1) -> List[int]:
    n = num_vertices
    if n <= 0:
        return []
    edges = [tuple(e) for e in edges]
    k = 1
    classical = None
    while k <= n:
        classical = _backtrack(n, edges, k)
        if classical is not None:
            break
        k += 1
    if classical is None:
        classical = list(range(n))
        k = n
    if k == 1:
        return [0] * n
    b = int(np.ceil(np.log2(k)))
    nq = n * b
    if nq > 16:
        return classical
    try:
        N = 1 << nq
        mask = (1 << b) - 1
        idx = np.arange(N)
        cols = [(idx >> (b * v)) & mask for v in range(n)]
        good = np.ones(N, dtype=bool)
        for v in range(n):
            good &= cols[v] < k
        for u, v in edges:
            if u != v:
                good &= cols[u] != cols[v]
        M = int(good.sum())
        if M == 0:
            return classical
        psi = np.ones(N) / np.sqrt(N)
        iters = max(0, int(num_iterations))
        for _ in range(iters):
            psi = np.where(good, -psi, psi)
            mean = psi.mean()
            psi = 2 * mean - psi
        probs = psi ** 2
        best = int(np.argmax(np.where(good, probs, -1)))
        res = [int((best >> (b * v)) & mask) for v in range(n)]
        if _valid(res, edges, k):
            return res
    except Exception:
        pass
    return classical

