def triangle_graph_oracle(qc: QuantumCircuit, colors: list, target: int) -> QuantumCircuit:
    k = len(colors[0])
    controls = list(colors[0]) + list(colors[1]) + list(colors[2])
    n = len(controls)
    m = 1 << k
    for a in range(m):
        for b in range(m):
            if b == a:
                continue
            for c in range(m):
                if c == a or c == b:
                    continue
                cs = a | (b << k) | (c << (2 * k))
                qc.append(MCXGate(n, ctrl_state=cs), controls + [target])
    return qc

