        for m in range(j - 1, -1, -1):
            qc2.cp(-np.pi / (2 ** (j - m)), q[m], q[j])
        qc2.h(q[j])
    sv = Statevector(qc2)
    probs = sv.probabilities(q)
    return int(np.argmax(probs))

