import numpy as np
from qiskit import QuantumCircuit
from typing import List


def _qft_circ(n):
    sub = QuantumCircuit(n)
    for j in range(n):
        sub.h(j)
        for k in range(j + 1, n):
            sub.cp(2 * np.pi / (2 ** (k - j + 1)), k, j)
    for i in range(n // 2):
        sub.swap(i, n - 1 - i)
    return sub


def qft_power(qc: QuantumCircuit, P: int, input_register: List[int]) -> QuantumCircuit:
    n = len(input_register)
    r = P % 4
    if n == 0 or r == 0:
        return qc
    reg = list(input_register)
    if r == 1:
        qc.compose(_qft_circ(n), qubits=reg, inplace=True)
    elif r == 3:
        qc.compose(_qft_circ(n).inverse(), qubits=reg, inplace=True)
    else:
        # x -> -x mod 2^n, reg[0] is the most significant bit
        for q in reg:
            qc.x(q)
        for i in range(n - 1):
            controls = reg[i + 1:]
            if len(controls) == 1:
                qc.cx(controls[0], reg[i])
            else:
                qc.mcx(controls, reg[i])
        qc.x(reg[n - 1])
    return qc

