def oracle_sat_clause(qc: QuantumCircuit, query_qubits: list, target: int,
                      clause: List[Tuple[int, bool]]) -> QuantumCircuit:
    signs = {}
    tautology = False
    for (j, pos) in clause:
        pos = bool(pos)
        if j in signs and signs[j] != pos:
            tautology = True
        signs[j] = pos
    if tautology:
        qc.x(target)
        return qc
    if len(signs) == 0:
        return qc
    # OR(literals) = NOT AND(NOT literals)
    flips = [query_qubits[j] for j, pos in signs.items() if pos]
    controls = [query_qubits[j] for j in signs]
    for q in flips:
        qc.x(q)
    qc.mcx(controls, target)
    for q in flips:
        qc.x(q)
    qc.x(target)
    return qc

