from typing import List, Tuple


def oracle_sat(qc: QuantumCircuit, query_qubits: list[int], target: int,
               problem: List[List[Tuple[int, bool]]]) -> QuantumCircuit:
    used = sorted({j for clause in problem for (j, _) in clause})
    n = len(used)
    pos = {v: i for i, v in enumerate(used)}
    for a in range(1 << n):
        ok = True
        for clause in problem:
            sat = False
            for (j, p) in clause:
                bit = (a >> pos[j]) & 1
                if (bit == 1) == bool(p):
                    sat = True
                    break
            if not sat:
                ok = False
                break
        if not ok:
            continue
        controls = [query_qubits[v] for v in used]
        zeros = [query_qubits[used[i]] for i in range(n) if ((a >> i) & 1) == 0]
        for q in zeros:
            qc.x(q)
        if len(controls) == 0:
            qc.x(target)
        elif len(controls) == 1:
            qc.cx(controls[0], target)
        else:
            qc.mcx(controls, target)
        for q in zeros:
            qc.x(q)
    return qc

