from qiskit import QuantumCircuit
from typing import List, Callable
import math


def grover_iteration(qc: QuantumCircuit, register: List[int], oracle_func: Callable[[QuantumCircuit, List[int]], QuantumCircuit]) -> QuantumCircuit:
    """
    Perform one Grover iteration.
    """
    res = oracle_func(qc, register)
    if res is not None:
        qc = res
    for q in register:
        qc.h(q)
    # conditional phase shift: flip phase of |0...0>
    for q in register:
        qc.x(q)
    if len(register) == 1:
        qc.z(register[0])
    else:
        qc.mcp(math.pi, list(register[:-1]), register[-1])
    for q in register:
        qc.x(q)
    for q in register:
        qc.h(q)
    return qc

