from qiskit import QuantumCircuit, ClassicalRegister, QuantumRegister, transpile
from qiskit_aer import AerSimulator
import numpy as np
from typing import Callable


def grover_diffusion_operator(qc: QuantumCircuit, register: list) -> QuantumCircuit:
    register = list(register)
    n = len(register)
    if n == 0:
        return qc
    for q in register:
        qc.h(q)
    for q in register:
        qc.x(q)
    if n == 1:
        qc.z(register[0])
    else:
        target = register[-1]
        qc.h(target)
        qc.mcx(register[:-1], target)
        qc.h(target)
    for q in register:
        qc.x(q)
    for q in register:
        qc.h(q)
    return qc


def grovers_search(n_qubits: int, oracle: Callable, iterations: int = None) -> dict:
    n = n_qubits
    qr = QuantumRegister(n, 'q')
    cr = ClassicalRegister(n, 'c')
    qc = QuantumCircuit(qr, cr)
    reg = list(range(n))
    if iterations is None:
        iterations = max(1, int(np.floor(np.pi / 4 * np.sqrt(2 ** n))))
    for q in reg:
        qc.h(q)
    for _ in range(iterations):
        res = oracle(qc, reg)
        if isinstance(res, QuantumCircuit) and res is not qc:
            qc.compose(res, qubits=list(range(res.num_qubits)), inplace=True)
        grover_diffusion_operator(qc, reg)
    for i in range(n):
        qc.measure(i, i)
    sim = AerSimulator()
    tqc = transpile(qc, sim)
    result = sim.run(tqc, shots=1024).result()
    counts = result.get_counts()
    return dict(counts)

