def win_condition(row_index, column_index, row, column):
    if not valid_alice_move(row) or not valid_bob_move(column):
        return False
    return row[column_index] == column[row_index]

def alice_classical(row_index):
    strategies = [
        [1, 1, 1],
        [1, -1, -1],
        [-1, 1, -1]
    ]
    return strategies[row_index]

def bob_classical(column_index):
    strategies = [
        [1, 1, -1],
        [1, -1, 1],
        [-1, -1, -1]
    ]
    return strategies[column_index]

def _square():
    I = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    k = np.kron
    return [
        [k(X, I), k(I, X), k(X, X)],
        [-k(X, Z), -k(Z, X), k(Y, Y)],
        [k(Z, I), k(I, Z), k(Z, Z)],
    ]

def _projectors(obs, parity):
    res = {}
    d = obs[0].shape[0]
    for s in itertools.product([1, -1], repeat=3):
        if int(np.prod(s)) != parity:
            continue
        P = np.eye(d, dtype=complex)
        for si, o in zip(s, obs):
            P = P @ (np.eye(d) + si * o) / 2
        res[s] = P
    return res

def _quantum_win_rate():
    M = _square()
    # state: (|00>+|11>)/sqrt2 on (a1,b1) and (a2,b2); ordering a1 a2 b1 b2
    psi = np.zeros(16, dtype=complex)
    for i in range(2):
        for j in range(2):
            idx = (i << 3) | (j << 2) | (i << 1) | j
            psi[idx] = 0.5
    total = 0.0
    for r in range(3):
        a_proj = _projectors(M[r], 1)
        for c in range(3):
            col_obs = [M[rr][c].T for rr in range(3)]
            b_proj = _projectors(col_obs, -1)
            for a, Pa in a_proj.items():
                for b, Pb in b_proj.items():
                    if win_condition(r, c, list(a), list(b)):
                        op = np.kron(Pa, Pb)
                        v = op @ psi
                        total += float(np.real(np.vdot(psi, v)))
    return total / 9.0

def test_magic_square_strategies():
    wins = 0
    for r in range(3):
        for c in range(3):
            if win_condition(r, c, alice_classical(r), bob_classical(c)):
                wins += 1
    classical_rate = wins / 9.0
    quantum_rate = _quantum_win_rate()
    quantum_rate = round(quantum_rate, 10)
    classical_ok = classical_rate <= 8.0 / 9.0 + 1e-9
    quantum_ok = abs(quantum_rate - 1.0) < 1e-6
    return {
        'classical_win_rate': classical_rate,
        'quantum_win_rate': quantum_rate,
        'classical_wins': wins,
        'classical_total': 9,
        'classical_passed': classical_ok,
        'quantum_passed': quantum_ok,
        'passed': classical_ok and quantum_ok,
        'success': classical_ok and quantum_ok,
    }

