def high_bit_sum(qc: QuantumCircuit, a: int, b: int, carry_in: int, sum_qubit: int) -> QuantumCircuit:
    # Apply X gates to input qubits based on classical bits a, b, and carry_in
    if a:
        qc.x(0)
    if b:
        qc.x(1)
    if carry_in:
        qc.x(2)

    # Implement three-way XOR using CNOT gates
    # XOR of a and b
    qc.cx(0, sum_qubit)
    qc.cx(1, sum_qubit)
    # XOR of (a XOR b) with carry_in
    qc.cx(2, sum_qubit)

    # Reverse the X gates to restore original state if needed (not strictly necessary for sum)
    if a:
        qc.x(0)
    if b:
        qc.x(1)
    if carry_in:
        qc.x(2)

    return qc

