def arbitrary_adder(qc: QuantumCircuit, a: list, b: list, sum_qubits: list, carry: int) -> QuantumCircuit:
    n = len(a)
    s = list(sum_qubits)
    if len(s) < n + 1:
        s = s + [carry]
    # compute carries: c_{i+1} stored in s[i+1], c_0 = 0
    for i in range(n):
        qc.ccx(a[i], b[i], s[i + 1])
        if i > 0:
            qc.ccx(a[i], s[i], s[i + 1])
            qc.ccx(b[i], s[i], s[i + 1])
    for i in range(n):
        qc.cx(a[i], s[i])
        qc.cx(b[i], s[i])
    return qc

