def subtractor(qc: QuantumCircuit, a: list, b: list, borrow_bit: int) -> QuantumCircuit:
    n = len(b)
    r = list(b) + [borrow_bit]
    m = n + 1
    # b - a = ~(~b + a)
    for q in b:
        qc.x(q)
    # QFT (no swaps)
    for j in reversed(range(m)):
        qc.h(r[j])
        for k in reversed(range(j)):
            qc.cp(pi / 2 ** (j - k), r[k], r[j])
