    for j in range(m):
        for i in range(min(j + 1, len(a))):
            qc.cp(pi / 2 ** (j - i), a[i], r[j])
    # inverse QFT
    for j in range(m):
        for k in range(j):
            qc.cp(-pi / 2 ** (j - k), r[k], r[j])
        qc.h(r[j])
    for q in b:
        qc.x(q)
    return qc

