def adder_modulo_n(qc: QuantumCircuit, a: list, b: list, sum_qubits: list) -> QuantumCircuit:
    n = len(sum_qubits)
    qft = QuantumCircuit(n)
    for j in reversed(range(n)):
        qft.h(j)
        for k in range(j - 1, -1, -1):
            qft.cp(math.pi / (2 ** (j - k)), k, j)
    qc.compose(qft, qubits=list(sum_qubits), inplace=True)
    for reg in (a, b):
        for j in range(n):
            for k in range(min(len(reg), j + 1)):
                qc.cp(2 * math.pi / (2 ** (j - k + 1)), reg[k], sum_qubits[j])
    qc.compose(qft.inverse(), qubits=list(sum_qubits), inplace=True)
    return qc

