def twos_complement(qc: QuantumCircuit, a: list) -> QuantumCircuit:
    n = len(a)
    # invert all bits
    for q in a:
        qc.x(q)
    # increment by 1 (little-endian: a[0] is least significant)
    for i in range(n - 1, 0, -1):
        qc.mcx(list(a[:i]), a[i])
    if n > 0:
        qc.x(a[0])
    return qc

