    for i in range(n // 2):
        qc.swap(b[i], b[n - 1 - i])
    for j in range(n):
        for k in range(j):
            qc.cp(-math.pi / (2 ** (j - k)), b[k], b[j])
        qc.h(b[j])

def in_place_subtractor_modulo_n(qc: QuantumCircuit, a: list, b: list) -> QuantumCircuit:
    n = len(b)
    _qft(qc, b)
    for j in range(n):
        for i in range(min(len(a), n)):
            if i + j < n:
                qc.cp(-2 * math.pi / (2 ** (n - i - j)), a[i], b[j])
    _iqft(qc, b)
    return qc

